value_escaped:
cbuffer tracer : register(b0) {
    float2 viewport;
    float start_fade;
    float end_fade;
    float4 endpoints;
    float4 perspective;
    float4 color;
    float4 shape;
    float4 glow;
    float4 quad01;
    float4 quad23;
};

struct vs_output {
    float4 position : SV_Position;
};

vs_output vs_main(uint id : SV_VertexID) {
    uint corner = id < 3 ? id : (id == 3 ? 0 : id - 2);
    float2 p = corner == 0 ? quad01.xy : (corner == 1 ? quad01.zw : (corner == 2 ? quad23.xy : quad23.zw));
    vs_output output;
    output.position = float4(p / viewport * float2(2.0, -2.0) + float2(-1.0, 1.0), 0.0, 1.0);
    return output;
}

// neverlose's PS 0xf07060 (tools/re/nl/shaders/f07060.txt), instruction for instruction.
float4 ps_main(vs_output input) : SV_Target {
    float2 p = input.position.xy;
    float2 a = endpoints.xy;
    float2 ab = endpoints.zw - endpoints.xy;
    float len2 = dot(ab, ab);
    float t = len2 > 0.0 ? saturate(dot(p - a, ab) / len2) : (shape.x >= shape.y ? 0.0 : 1.0);
    float2 dv = p - (a + t * ab);
    float d2 = dot(dv, dv);
    float d = sqrt(d2);
    float hw = lerp(shape.x, shape.y, t);
    float gr = lerp(shape.z, shape.w, t);
    float e = d - hw;
    float aa = max(abs(ddx_coarse(e)) + abs(ddy_coarse(e)), 1.0);
    float glow_a = saturate(1.0 - max(e, 0.0) / gr);
    float core = saturate((hw - d) / aa + 0.5) - saturate((-d - hw) / aa + 0.5);
    float w = max(lerp(perspective.x, perspective.y, t), 0.0);
    float u = perspective.z + (t * perspective.y / w) * (perspective.w - perspective.z);
    float fs = start_fade > 0.0 ? saturate(u / start_fade) : 1.0;
    float fe = end_fade > 0.0 ? saturate((1.0 - u) / end_fade) : 1.0;
    float fade = fs * fe;
    float highlight = max(1.0 - d2 / max(hw * hw, 0.0), 0.0) * core * fade * color.a * 0.25;
    float glow_t = (glow.x > 0.0 && gr > 0.0) ? glow_a * glow_a * glow_a * glow.x : 0.0;
    float alpha = fade * max(glow_t, core) * color.a;
    return float4(color.rgb * alpha + highlight * (1.0 - color.rgb), alpha);
}

