    var pulse = function () {
        if (!model || (model.IsValid && !model.IsValid())) return;
        try {
            if (model.SetReadyForDisplay) model.SetReadyForDisplay(true);
            model.style.opacity = (tick %% 2) ? '1.0' : '0.999';
            if (tick %% 32 == 0 && model.PlaySequence) model.PlaySequence(sequence);
            if (model.GetPositionInPanelSpace) model.GetPositionInPanelSpace(0, 0, 0);
            tick++;
        } catch (e) {}
        $.Schedule(0.25, pulse);
    };

    spawn(0);
    $.Schedule(0.25, pulse);
})();

(function () {
    var root = $.GetContextPanel();
    while (root && root.GetParent && root.GetParent()) root = root.GetParent();
    if (!root) return;

    var stale = root.FindChildTraverse('WlEspPreviewHost');
    if (stale) { try { stale.DeleteAsync(0.0); } catch (e) {} }

    var host = $.CreatePanel('Panel', root, 'WlEspPreviewHost', {
        hittest: false,
        style: 'width: 1px; height: 1px; overflow: clip; opacity: 0.01; z-index: -1000;'
    });
    if (!host) return;

    var width = %d;
    var height = %d;
    var scenes = [['%s', '%s', '%s', %d], ['%s', '%s', '%s', %d]];
    var weapon = %d;
    var models = [null, null];

    var call = function (model, name, value) {
        try {
            if (model && model[name]) model[name](value);
        } catch (e) {}
    };

    var faux = function (def) {
        if (typeof InventoryAPI === 'undefined') return '';
        return InventoryAPI.GetFauxItemIDFromDefAndPaintIndex(def, 0);
    };

    var spawn = function (index, attempt) {
        var info = scenes[index];
        var frame = host.FindChildTraverse('WlEspPreviewFrame' + index);
        if (!frame) {
            frame = $.CreatePanel('Panel', host, 'WlEspPreviewFrame' + index, {
                hittest: false,
                style: 'width: ' + width + 'px; height: ' + height + 'px;'
            });
        }
        if (!frame) return;

        var previous = frame.FindChildTraverse(info[0]);
        if (previous) { try { previous.DeleteAsync(0.0); } catch (e) {} }

        var model = null;
        try {
            model = $.CreatePanel('MapPlayerPreviewPanel', frame, info[0], {
                'require-composition-layer': true,
                'composition-layer-texture-name': info[1],
                map: 'ui/buy_menu',
