                hittest: false,
                style: 'width: ' + width + 'px; height: ' + height + 'px; background-color: transparent; z-index: 9999;'
            });
        } catch (e) {
            model = null;
        }
        models[index] = model;

        if (!model) {
            if (attempt < 3) $.Schedule(0.1, function () { spawn(index, attempt + 1); });
            return;
        }

        call(model, 'SetPlayerModel', '%s');
        call(model, 'EquipPlayerWithItem', faux(weapon));
        call(model, 'SetHideStaticGeometry', true);
        call(model, 'SetHideParticles', true);
        call(model, 'SetTransparentBackground', true);

        $.Schedule(0.3, function () {
            if (!model || (model.IsValid && !model.IsValid())) return;
            call(model, 'SetPlayerCharacterItemID', faux(info[3]));
            call(model, 'SetPlayerModel', info[2]);
            call(model, 'EquipPlayerWithItem', faux(weapon));
            $.Msg('[neverlose] esp preview | scene ' + index + ' agent ' + info[3] + ' model ' + info[2]);
        });

        $.Schedule(1.5, function () {
            if ((!model || (model.IsValid && !model.IsValid())) && attempt < 3) spawn(index, attempt + 1);
        });
    };

    var tick = 0;
    var pulse = function () {
        var alive = false;
        for (var i = 0; i < models.length; i++) {
            var model = models[i];
            if (!model || (model.IsValid && !model.IsValid())) continue;
            alive = true;
            try {
                if (model.SetReadyForDisplay) model.SetReadyForDisplay(true);
                model.style.opacity = (tick %% 2) ? '1.0' : '0.999';
                if (model.GetPositionInPanelSpace) model.GetPositionInPanelSpace(0, 0, 0);
            } catch (e) {}
        }
        tick++;
        if (alive || tick < 40) $.Schedule(0.25, pulse);
    };

    spawn(0, 0);
    spawn(1, 0);
    $.Schedule(0.25, pulse);
})();

