(function () {
    var root = $.GetContextPanel();
    while (root && root.GetParent && root.GetParent()) root = root.GetParent();
    if (!root) return;
    var keep = root.Data();
    var plain = function (text) { return String(text).replace(/[<>;"'\\]/g, ''); };
    keep.wlLocal = function (token, arg) {
        var text = token;
        try { if (token && token.charAt(0) === '#') text = $.Localize(token); } catch (e) {}
        var value = arg;
        try { if (arg && arg.charAt(0) === '#') value = $.Localize(arg); } catch (e) {}
        if (value) text = String(text).replace('%s1', value);
        return plain(text);
    };
    keep.wlSay = function (text, chat, console) {
        if (console) { try { GameInterfaceAPI.ConsoleCommand('echo neverlose \u00bb ' + plain(text)); } catch (e) {} }
        if (!chat) return;
        try {
            var lines = root.FindChildTraverse('ChatLinesContainer');
            if (!lines) return;
            var line = $.CreatePanel('Label', lines, '', { class: 'chat-entry', html: 'true' });
            if (!line) return;
            line.html = true;
            line.text = "<font color='#96A4FF'>neverlose</font> \u00bb " + plain(text);
        } catch (e) {}
    };
    keep.wlVoteStart = function (chat, console, by) {
        var text = '';
        try {
            var vote = root.FindChildTraverse('HudVote');
            var label = vote ? vote.FindChildTraverse('VoteDescLabel') : null;
            if (label && label.text) text = label.text;
        } catch (e) {}
        keep.wlSay('vote started' + (text ? ': ' + plain(text) : '') + (by ? ' (by ' + by + ')' : ''), chat, console);
    };
})();

(function (gen) {
if (typeof WlNlScoreboard !== 'undefined' && WlNlScoreboard && WlNlScoreboard.reset) {
try { WlNlScoreboard.reset(); } catch (e) {}
	}

	var S = {
		o: 88, w: 100, money: false, equip: 0,
		players: {}, cursor: 0, root: null, key: '', force: true,
		rows: {}, revealed: {}, boxes: [], handlers: [], said: {}
	};

	var ICON_STYLE = [
		['marginLeft', '1px'], ['marginRight', '1px'], ['uiScale', '45%'], ['verticalAlign', 'middle'],
		['transitionProperty', 'opacity'], ['transitionDuration', '0.1s'], ['transitionTimingFunction', 'ease-in-out']
	];

	function ok(p) { return !!p && typeof p.IsValid === 'function' && p.IsValid(); }

	function say(key, text) {
		if (S.said[key]) return;
		S.said[key] = true;
		$.Msg('[neverlose] scoreboard | ' + text);
	}

	function all(r, cls) {
		try { return r.FindChildrenWithClassTraverse(cls) || []; } catch (e) { return []; }
	}

	function insideEndOfMatch(p) {
		for (var q = p; ok(q); q = q.GetParent()) {
			if (typeof q.id === 'string' && q.id.indexOf('EndOfMatch') >= 0) return true;
		}
		return false;
	}

	function board() {
		if (ok(S.root)) return S.root;
		var ctx = $.GetContextPanel();
		if (!ok(ctx)) return null;
		var found = null;
		var spare = null;
		var mains = all(ctx, 'sb-main');
		for (var i = 0; i < mains.length && !found; ++i) {
			if (insideEndOfMatch(mains[i])) continue;
			var top = null;
			for (var q = mains[i]; ok(q) && q !== ctx; q = q.GetParent()) {
				top = q;
				if (q.paneltype === 'CSGOScoreboard') {
					found = q;
					break;
				}
			}
			if (!spare) spare = top;
		}
		if (!found && spare) {
			found = spare;
			say('spare', 'no CSGOScoreboard above .sb-main, using ' + spare.paneltype + ' #' + spare.id);
		}
		if (!found) return null;
		S.root = found;
		S.rows = {};
		S.key = '';
		S.force = true;
		say('root:' + found.id, 'root ' + found.paneltype + ' #' + found.id);
		return found;
	}

	function setWidth(p, value) {
		if (!ok(p)) return;
		if (!p.BHasClass('nl-scoreboard-width')) p.AddClass('nl-scoreboard-width');
		p.style.width = value.toFixed(2) + 'px';
	}

	function layout(force) {
		var r = board();
		if (!r) return;
		var key = S.o + ':' + S.w;
		if (!force && !S.force && S.key === key) return;
		S.key = key;
		S.force = false;
		var mains = all(r, 'sb-main');
		for (var i = 0; i < mains.length; ++i) {
			var m = mains[i];
			if (!ok(m)) continue;
			if (S.o === 88) {
				if (m.BHasClass('nl-scoreboard-color')) {
					m.style.backgroundColor = null;
					m.RemoveClass('nl-scoreboard-color');
				}
			} else {
				if (!m.BHasClass('nl-scoreboard-color')) m.AddClass('nl-scoreboard-color');
				m.style.backgroundColor = 'rgba(0,0,0,' + (Math.floor(S.o * 255 / 100) / 255).toFixed(4) + ')';
			}
		}
		if (S.w === 100) {
			var wide = all(r, 'nl-scoreboard-width');
			for (var j = 0; j < wide.length; ++j) {
				if (!ok(wide[j])) continue;
				wide[j].style.width = null;
				wide[j].RemoveClass('nl-scoreboard-width');
			}
			return;
		}
		var extra = (S.w - 100) * 960 / 100;
		var rows = all(r, 'sb-row');
		for (var a = 0; a < rows.length; ++a) setWidth(rows[a], 830 + extra);
		var high = all(r, 'highlight-row');
		for (var b = 0; b < high.length; ++b) setWidth(high[b], 770 + extra);
		var meta = all(r, 'meta-row');
		for (var c = 0; c < meta.length; ++c) setWidth(meta[c], 860 + extra);
		setWidth(r.FindChildTraverse('id-sb-players-table__labels-row__inner'), 770 + extra);
	}

	function rowOf(slot, xuid, r) {
		var cached = S.rows[slot];
		if (cached && cached.x === xuid && ok(cached.row)) return cached.row;
		delete S.rows[slot];
		var row = r.FindChildTraverse('player-' + xuid);
		if (!ok(row)) return null;
		S.rows[slot] = { x: xuid, row: row };
		return row;
	}

	function reveal(slot, cell, money) {
		var label = cell.FindChildTraverse('label');
		if (!ok(label)) return;
		var kept = S.revealed[slot];
		if (!kept || kept.label !== label || !ok(kept.label)) S.revealed[slot] = { label: label, hidden: label.BHasClass('hidden') };
		label.SetHasClass('hidden', false);
		label.SetDialogVariableInt('stat_d_money', money);
	}

	function unreveal() {
		for (var s in S.revealed) {
			var k = S.revealed[s];
			if (k && ok(k.label)) k.label.SetHasClass('hidden', k.hidden);
		}
		S.revealed = {};
	}

	function container(cell) {
		var box = cell.FindChildTraverse('nl_weapons');
		if (ok(box)) {
			if (S.boxes.indexOf(box) < 0) S.boxes.push(box);
			return box;
		}
