cbuffer fx_constants : register(b0) {
    float4 screen;
    float4 rain;
    float4 fog;
    float4 flags;
};

Texture2D scene_texture : register(t0);
SamplerState scene_sampler : register(s0);

struct vs_output {
    float4 position : SV_Position;
    float2 uv : TEXCOORD0;
};

vs_output vs_main(uint id : SV_VertexID) {
    vs_output output;
    float2 uv = float2((id << 1) & 2, id & 2);
    output.uv = uv;
    output.position = float4(uv * float2(2.0, -2.0) + float2(-1.0, 1.0), 0.0, 1.0);
    return output;
}

float3 n13(float p) {
    float3 p3 = frac(p * float3(0.1031, 0.11369, 0.13787));
    p3 += dot(p3, p3.yzx + 19.19);
    return frac(float3((p3.x + p3.y) * p3.z, (p3.x + p3.z) * p3.y, (p3.y + p3.z) * p3.x));
}

float n1(float t) {
    return frac(sin(t * 12345.564) * 7658.76);
}

float saw(float b, float t) {
    return smoothstep(0.0, b, t) * smoothstep(1.0, b, t);
}

float2 drop_layer(float2 uv, float t) {
    float2 uv0 = uv;
    uv.y += t * 0.75;
    float2 a = float2(6.0, 1.0);
    float2 grid = a * 2.0;
    float2 id = floor(uv * grid);
    uv.y += n1(id.x);
    id = floor(uv * grid);
    float3 n = n13(id.x * 35.2 + id.y * 2376.1);
    float2 st = frac(uv * grid) - float2(0.5, 0.0);
    float x = n.x - 0.5;
    float y = uv0.y * 20.0;
    float wiggle = sin(y + sin(y));
    x += wiggle * (0.5 - abs(x)) * (n.z - 0.5);
    x *= 0.7;
    float ti = frac(t + n.z);
    y = (saw(0.85, ti) - 0.5) * 0.9 + 0.5;
    float d = length((st - float2(x, y)) * a.yx);
    float main_drop = smoothstep(0.4, 0.0, d);
    float r = sqrt(smoothstep(1.0, y, st.y));
    float cd = abs(st.x - x);
    float trail = smoothstep(0.23 * r, 0.15 * r * r, cd);
    float trail_front = smoothstep(-0.02, 0.02, st.y - y);
    trail *= trail_front * r * r;
    y = frac(uv0.y * 10.0) + (st.y - 0.5);
    float droplets = smoothstep(0.3, 0.0, length(st - float2(x, y)));
    return float2(main_drop + droplets * r * trail_front, trail);
}

float static_drops(float2 uv, float t) {
    uv *= 40.0;
    float2 id = floor(uv);
    uv = frac(uv) - 0.5;
    float3 n = n13(id.x * 107.45 + id.y * 3543.654);
    float2 p = (n.xy - 0.5) * 0.7;
    float d = length(uv - p);
    float fade = saw(0.025, frac(t + n.z));
    return smoothstep(0.3, 0.0, d) * frac(n.z * 10.0) * fade;
}

float2 drops(float2 uv, float t, float l0, float l1, float l2) {
    float s = static_drops(uv, t) * l0;
    float2 m1 = drop_layer(uv, t) * l1;
    float2 m2 = drop_layer(uv * 1.85, t) * l2;
    float c = smoothstep(0.3, 1.0, s + m1.x + m2.x);
    return float2(c, max(m1.y * l0, m2.y * l1));
}

float3 fetch(float2 uv, float lod) {
    float radius = exp2(lod) - 1.0;
    float3 result = 0.0;
    [branch]
    if (flags.w > 1.5 || radius < 0.5) {
        result = scene_texture.SampleLevel(scene_sampler, uv, flags.w > 1.5 ? lod : 0.0).rgb;
    } else {
        [unroll]
        for (int i = 0; i < 12; i++) {
            float angle = i * 2.39996;
            float spread = sqrt((i + 0.5) / 12.0) * radius;
            result += scene_texture.SampleLevel(scene_sampler, uv + float2(cos(angle), sin(angle)) * spread * screen.zw, 0).rgb;
        }
        result /= 12.0;
    }
    return result;
}

float3 sample_scene(float2 uv, float lod) {
    float2 shift = (uv - 0.5) * fog.z * 2.0 * flags.y;
    float r = fetch(uv + shift, lod).r;
    float g = fetch(uv, lod).g;
    float b = fetch(uv - shift, lod).b;
    return float3(r, g, b);
}

float4 ps_main(vs_output input) : SV_Target {
    float2 uv = input.uv;
    float aspect = screen.x * screen.w;
    float3 color;
    if (flags.x > 0.5) {
        float2 p = float2((uv.x - 0.5) * aspect, 0.5 - uv.y) * (0.7 / max(rain.z, 0.2));
        float t = rain.x * rain.w * 0.2;
        float amount = rain.y;
        float l0 = smoothstep(-0.5, 1.0, amount) * 2.0;
        float l1 = smoothstep(0.25, 0.75, amount);
        float l2 = smoothstep(0.0, 0.5, amount);
        float2 c = drops(p, t, l0, l1, l2);
        float2 e = float2(0.001, 0.0);
        float cx = drops(p + e, t, l0, l1, l2).x;
        float cy = drops(p + e.yx, t, l0, l1, l2).x;
        float2 n = float2(cx - c.x, cy - c.x);
        float max_blur = lerp(3.0, 6.0, amount) * fog.y;
        float focus = lerp(max_blur - c.y, 1.0, smoothstep(0.1, 0.2, c.x));
        color = sample_scene(uv + float2(n.x, -n.y), max(focus, 0.0) * fog.x);
    } else {
        color = sample_scene(uv, 0.0);
    }
    if (flags.z > 0.5) {
        float2 d = (uv - 0.5) * float2(aspect, 1.0);
        color *= 1.0 - smoothstep(0.35, 1.05, length(d)) * fog.w;
    }
    float alpha = scene_texture.SampleLevel(scene_sampler, uv, 0).a;
    return float4(max(color, 0.0), alpha);
}

cbuffer blur_constants : register(b0) {
