float4 ps_main(vs_output input) : SV_Target {
    float sigma = step_sigma.z;
    float3 color = 0.0;
    float total = 0.0;
    [unroll] for (int i = -8; i <= 8; i++) {
        float weight = exp(-(i * i) / (2.0 * sigma * sigma));
        color += source.Sample(linear_sampler, input.uv + step_sigma.xy * i).rgb * weight;
        total += weight;
    }
    return float4(color / total, 1.0);
}

