cbuffer effect_constants : register(b0) {
    float4 effect_param;
};

Texture2D texture0 : register(t0);
SamplerState sampler0 : register(s0);

float4 ps_main(float4 position : SV_Position, float4 color : COLOR0, float2 uv : TEXCOORD0) : SV_Target {
    float4 c = color * texture0.Sample(sampler0, uv);
    float grey = (c.r + c.g + c.b) * (1.0 / 3.0);
    c.rgb = c.rgb + (grey - c.rgb) * effect_param.x;
    return c;
}

