    output.uv = uv;
    output.col = float4(1.0, 1.0, 1.0, 1.0);
    output.pos = float4(uv * float2(2.0, -2.0) + float2(-1.0, 1.0), 0.0, 1.0);
    return output;
}

float4 ps_main(vs_output input) : SV_Target {
    float a = (-input.uv.y - 1.0) * 1.570796;
    float b = (-0.5 * input.uv.x - 1.0) * 3.141593;
    float3 dir = float3(cos(b) * cos(a), sin(b) * cos(a), sin(-a));
    float4 c = texture0.Sample(sampler0, dir);
    float3 hi = pow(abs(c.rgb), 0.416667) * 1.055 - 0.055;
    float3 lo = c.rgb * 12.92;
    c.rgb = (c.rgb <= 0.003131) ? lo : hi;
    return c * input.col;
}

cbuffer quad_constants : register(b0) {
    float4 rect;      // min.x, min.y, max.x, max.y of the primitive
    float4 params;    // rounding, size, kind, smoothing (neverlose's rect_smoothing)
    float4 color;     // the shadow colour
    float4 display;   // width, height, exact radius (inline primitives), 0
    float4 extra;
    float4 color2;
};

Texture2D blurred : register(t0);
SamplerState linear_sampler : register(s0);

struct vs_output {
    float4 position : SV_Position;
    float2 pixel : TEXCOORD0;
};

vs_output vs_main(uint id : SV_VertexID) {
    // Shadows, glows and the bar reach size / 2 past the shape; every kind 2 more pixels for the antialiased edge
    // (|ddx d| + |ddy d| is up to 1.41 at a corner).
    float reach = ((params.z < 1.5 || (params.z > 3.5 && params.z < 5.5)) ? params.y * 0.5 + length(extra.xy) : 0.0) + 2.0;
    float2 corner = float2((id == 1 || id == 2 || id == 4) ? 1.0 : 0.0, (id == 2 || id == 4 || id == 5) ? 1.0 : 0.0);
    float2 lo = rect.xy - reach;
    float2 hi = rect.zw + reach;
    float2 pixel = lerp(lo, hi, corner);
    vs_output output;
    output.pixel = pixel;
    float2 ndc = pixel / display.xy * float2(2.0, -2.0) + float2(-1.0, 1.0);
    output.position = float4(ndc, 0.0, 1.0);
    return output;
}

// neverlose's rect distance (0xf3d2c0): a superellipse of exponent n = 2 + 3.6 * smoothing on the corners, the
// radius divided by max(1 - 0.6 * smoothing, 0.01); smoothing 0 is the ordinary rounded rect.
float rect_distance(float2 p, float2 half_size, float r, float smoothing) {
    float n = 2.0 + 3.6 * smoothing;
    float radius = r / max(1.0 - 0.6 * smoothing, 0.01);
    float2 q = abs(p) - half_size + radius;
    float2 m = max(q, 0.0);
    float outer = pow(pow(m.x, n) + pow(m.y, n), 1.0 / n);
    return outer + min(max(q.x, q.y), 0.0) - radius;
}

float4 ps_main(vs_output input) : SV_Target {
    float2 half_size = (rect.zw - rect.xy) * 0.5;
    float2 center = (rect.xy + rect.zw) * 0.5;
    // ImGui's AddRectFilled clamps the rounding to half the size minus 1: the same here, so the shadow follows the
    // shape ImGui draws over it.
    float r = max(min(params.x, min(half_size.x, half_size.y) - (display.z > 0.5 ? 0.0 : 1.0)), 0.0);
    float d = rect_distance(input.pixel - center, half_size, r, params.w);
    // The shape's outside, as the shader takes it for a filled rect (thickness 0): t = smoothstep(saturate((d + w) /
    // 2w)) with w = |ddx d| + |ddy d| (deriv_rtx/rty_coarse), i.e. a 2 w wide soft edge centred on it; a hard d >= 0
    // when no corner is rounded. The shape's alpha is colour.a * (1 - t). (The d + 0.5 smoothstep of the shader is
    // the outline path, rect_thickness > 0, which these never use.)
    float w = max(abs(ddx(d)) + abs(ddy(d)), 0.0001);
    float o = saturate((d + w) / (2.0 * w));
    o = o * o * (3.0 - 2.0 * o);
    float outside = r > 0.0 ? o : (d >= 0.0 ? 1.0 : 0.0);
    float size = max(params.y, 0.001);
    // The falloff of shadow_type 1 / 2: 1 - smoothstep(saturate((d + size / 2) / size)).
    float t = saturate((d + size * 0.5) / size);
    float falloff = 1.0 - t * t * (3.0 - 2.0 * t);
    if (params.z > 5.5) {
        float coverage = 1.0 - outside;
        float d_in = rect_distance(input.pixel + extra.xy - center, half_size, r, params.w);
        float g = saturate(-d_in / size);
        g = 1.0 - g * g * (3.0 - 2.0 * g);
        float3 rgb = coverage > 0.0 ? lerp(color.rgb, color2.rgb, color2.a * g) : color.rgb;
        return float4(rgb, color.a * coverage);
    }
    if (params.z > 4.5) {
        float d_off = rect_distance(input.pixel - extra.xy - center, half_size, r, params.w);
        float t_off = saturate((d_off + size * 0.5) / size);
        float f_off = 1.0 - t_off * t_off * (3.0 - 2.0 * t_off);
        return float4(color.rgb, color.a * f_off * outside);
    }
    if (params.z > 3.5) {
        // The accent bar (0x968f00): one multi-gradient primitive (prim_type 3, vertical: multi_is_horizontal 0)
        // with six stops (0: clear, 0.1: clear, 0.5: full, 0.5: full, 0.9: clear, 1: clear) of the colour, its glow
        // set on the same primitive (vtable +136, shadow_type 1, shadow colour = the colour at 0.75 of its alpha,
        // offset 0). The shader: inside the gradient colour times (1 - t); the glow's alpha = the gradient's alpha
        // at the pixel times the shadow alpha times the falloff; the two lerped by t.
        float v = (input.pixel.y - rect.y) / max(rect.w - rect.y, 0.001);
        float g = (v < 0.0 || v > 1.0) ? 0.0 : (v < 0.5 ? saturate((v - 0.1) / 0.4) : saturate((0.9 - v) / 0.4));
        float gradient_alpha = color.a * g;
        float fill_alpha = gradient_alpha * (1.0 - outside);
        float glow_alpha = gradient_alpha * (0.75 * color.a) * falloff;
        return float4(color.rgb, lerp(fill_alpha, glow_alpha, outside));
    }
    if (params.z > 1.5) {
        // The shape (fill), or the blurred frame through it (the panel's flag 0x20 -> uv_rule 2).
        float coverage = 1.0 - outside;
        if (params.z > 2.5) {
            float3 rgb = blurred.Sample(linear_sampler, input.pixel / display.xy).rgb * color.rgb;
            return float4(rgb, color.a * coverage);
        }
        return float4(color.rgb, color.a * coverage);
    }
    // A shadow primitive (0x960b20, shadow_type 2) outputs only t times the falloff times the shadow's alpha.
    float alpha = color.a * falloff * outside;
    if (params.z > 0.5) {
        // The glow follows the primitive's own vertical gradient: 0 at 0.1, 1 at 0.5, 0 at 0.9 of its height.
        float v = (input.pixel.y - rect.y) / max(rect.w - rect.y, 0.001);
        float g = v < 0.5 ? saturate((v - 0.1) / 0.4) : saturate((0.9 - v) / 0.4);
        alpha *= g;
    }
    return float4(color.rgb, alpha);
}

struct vs_output {
    float4 position : SV_Position;
    float2 uv : TEXCOORD0;
};

vs_output vs_main(uint id : SV_VertexID) {
    vs_output output;
    float2 uv = float2((id << 1) & 2, id & 2);
    output.uv = uv;
    output.position = float4(uv * float2(2.0, -2.0) + float2(-1.0, 1.0), 0.0, 1.0);
    return output;
}

struct neverwin_vs_output {
    float4 position : SV_Position;
    float2 uv : TEXCOORD0;
};

float3 neverwin_face_direction(uint face, float2 uv) {
    float2 t = uv * 2.0 - 1.0;
    float3 v;
    if (face == 0) v = float3(1.0, -t.y, -t.x);
    else if (face == 1) v = float3(-1.0, -t.y, t.x);
    else if (face == 2) v = float3(t.x, 1.0, t.y);
    else if (face == 3) v = float3(t.x, -1.0, -t.y);
    else if (face == 4) v = float3(t.x, -t.y, 1.0);
    else v = float3(-t.x, -t.y, -1.0);
    return normalize(v);
}

float4 neverwin_sky_main(neverwin_vs_output input) : SV_Target {
    float3 v = neverwin_face_direction((uint)Frame.x, input.uv);
    float3 color = EvaluateSky(normalize(v), Frame.z) * Frame.w;
    if (any(isnan(color)) || any(isinf(color))) color = 0.0;
    float luminance = dot(max(color, 0.0), float3(0.2126, 0.7152, 0.0722));
    float3 recolored = luminance * lerp(Primary.rgb, Secondary.rgb, smoothstep(0.0, 1.0, luminance)) * 1.5;
    color = lerp(color, recolored, saturate(neverwin_recolor.x));
    color *= neverwin_tint.rgb;
    float noise = frac(sin(dot(input.position.xy + Frame.x * 37.0, float2(12.9898, 78.233))) * 43758.5453) - 0.5;
    color *= 1.0 + noise * (1.0 / 96.0);
    return float4(max(color, 0.0), 1.0);
}

cbuffer neverwin_sky_constants : register(b0) {
    float4 Frame;
    float4 Primary;
    float4 Secondary;
    float4 neverwin_orientation;
    float4 neverwin_tint;
    float4 neverwin_recolor;
    float4 neverwin_parameters[8];
};

float Param(int index) {
    return neverwin_parameters[clamp(index, 0, 7)].x;
}

float3 Palette(float x) {
    return lerp(Primary.rgb, Secondary.rgb, saturate(x));
}

float Hash3(float3 p) {
    p = frac(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return frac((p.x + p.y) * p.z);
}

float Noise3(float3 p) {
    float3 i = floor(p);
    float3 f = frac(p);
    float3 u = f * f * (3.0 - 2.0 * f);
    float n000 = Hash3(i);
    float n100 = Hash3(i + float3(1.0, 0.0, 0.0));
    float n010 = Hash3(i + float3(0.0, 1.0, 0.0));
    float n110 = Hash3(i + float3(1.0, 1.0, 0.0));
    float n001 = Hash3(i + float3(0.0, 0.0, 1.0));
    float n101 = Hash3(i + float3(1.0, 0.0, 1.0));
    float n011 = Hash3(i + float3(0.0, 1.0, 1.0));
    float n111 = Hash3(i + float3(1.0, 1.0, 1.0));
    float x00 = lerp(n000, n100, u.x);
    float x10 = lerp(n010, n110, u.x);
    float x01 = lerp(n001, n101, u.x);
    float x11 = lerp(n011, n111, u.x);
    return lerp(lerp(x00, x10, u.y), lerp(x01, x11, u.y), u.z);
}

float Fbm3(float3 p) {
    float sum = 0.0;
    float amplitude = 0.5;
    [unroll]
    for (int i = 0; i < 5; i++) {
        sum += amplitude * Noise3(p);
        p = p * 2.03 + float3(17.1, 9.2, 3.7);
        amplitude *= 0.5;
    }
    return sum / 0.96875;
}

float3 neverwin_star_layer(float3 d, float scale, float size, float density, float time, float seed) {
    float3 p = d * scale;
    float3 cell = floor(p);
    float3 local = frac(p) - 0.5;
    float h = Hash3(cell + seed);
    float3 result = 0.0;
    [branch]
    if (h < density) {
        float3 offset = float3(Hash3(cell + seed + 11.3), Hash3(cell + seed + 23.7), Hash3(cell + seed + 37.1)) - 0.5;
        float3 delta = local - offset * 0.5;
        delta -= d * dot(delta, d);
        float distance_to_star = length(delta);
        float brightness = pow(saturate(1.0 - distance_to_star / size), 3.0);
        float twinkle = 0.7 + 0.3 * sin(time * (1.5 + h * 4.0) + h * 91.0);
        float3 tint = lerp(float3(1.0, 0.78, 0.6), float3(0.72, 0.82, 1.0), Hash3(cell + seed + 51.9));
        result = tint * brightness * twinkle * lerp(0.3, 1.6, Hash3(cell + seed + 71.3));
    }
    return result;
}

float3 SkyStars(float3 direction, float amount, float time) {
    float3 d = normalize(direction);
    float density = saturate(amount);
    float3 stars = neverwin_star_layer(d, 90.0, 0.35, density * 0.22, time, 0.0);
    stars += neverwin_star_layer(d, 210.0, 0.3, density * 0.35, time, 17.0);
    stars += neverwin_star_layer(d, 420.0, 0.28, density * 0.45, time, 43.0) * 0.6;
    return stars * max(amount, 0.0);
}

float3 SkyStarsFine(float3 direction, float amount, float time) {
    float3 d = normalize(direction);
    float density = saturate(amount);
    float3 stars = neverwin_star_layer(d, 70.0, 0.4, density * 0.2, time, 5.0);
    stars += neverwin_star_layer(d, 140.0, 0.34, density * 0.3, time, 29.0);
    return stars * max(amount, 0.0);
}

float3 AuroraCurtain(float3 d, float h, float t, float seed, float shift) {
    float3 sum = 0.0;
    [loop]
    for (int i = 0; i < 16; i++) {
        float rise = (float)i / 16.0;
        float2 p = d.xy / (h + 0.03) * (0.22 + rise * 0.16);
        float wander = (Noise3(float3(p.x * 0.35 + seed, seed * 3.0, t * 0.04)) - 0.5) * 3.0;
        float distance_to_line = abs(p.y - wander - shift);
        float line_glow = exp(-distance_to_line * distance_to_line * 60.0);
        float folds = Noise3(float3(p.x * 16.0 + t * 0.6 + seed, rise * 1.5, t * 0.35));
        float rays = 0.25 + 0.75 * pow(folds, 2.0);
        float3 tint = lerp(float3(0.12, 1.0, 0.45), float3(0.65, 0.2, 1.0), smoothstep(0.3, 1.0, rise));
        sum += tint * line_glow * rays * pow(1.0 - rise, 1.4);
    }
    return sum / 16.0;
}

float3 EvaluateSky(float3 direction, float time) {
    float3 d = normalize(direction);
    float h = d.z;
    float t = time * Param(0);

    float3 color = lerp(float3(0.02, 0.035, 0.06), float3(0.003, 0.005, 0.016), pow(saturate(h), 0.5));
    color += SkyStars(d, Param(2), time) * smoothstep(0.0, 0.15, h);

    float3 aurora = 0.0;
    [branch]
    if (h > 0.01) {
        aurora = AuroraCurtain(d, h, t, 0.0, 0.2) + AuroraCurtain(d, h, t * 0.8, 7.3, -0.6) * 0.7;
        aurora *= smoothstep(0.01, 0.2, h);
    }
    color += aurora * Param(1) * 3.0;
    color += float3(0.04, 0.1, 0.07) * Param(1) * exp(-abs(h) * 20.0) * 0.3;

    float3 ground = float3(0.01, 0.012, 0.018);
    return lerp(color, ground, smoothstep(0.0, -0.06, h));
}

float3 EvaluateSky(float3 direction, float time) {
    float3 d = normalize(direction);
    float h = d.z;

    float3 zenith = float3(0.004, 0.006, 0.02);
    float3 horizon = float3(0.025, 0.04, 0.085);
    float3 color = lerp(horizon, zenith, pow(saturate(h), 0.45));
    color += float3(0.1, 0.065, 0.045) * Param(2) * exp(-abs(h) * 12.0);

    float3 axis = normalize(float3(0.35, -0.55, 0.76));
    float across = dot(d, axis);
    float band = exp(-across * across * 16.0);
    float clumps = Fbm3(d * 9.0 + 7.7);
    float fine = Fbm3(d * 26.0 + 1.3);
    float dust = Fbm3(d * 5.0 + 3.1);
    float glow = band * (0.35 + 0.9 * smoothstep(0.35, 0.8, clumps)) * (0.7 + 0.5 * fine);
    float rift = smoothstep(0.5, 0.72, dust) * exp(-across * across * 70.0);
    float3 milky = lerp(float3(0.42, 0.4, 0.55), float3(1.0, 0.86, 0.7), smoothstep(0.4, 0.8, clumps));
    color += milky * glow * (1.0 - 0.85 * rift) * 0.22 * Param(1);

    float3 stars = SkyStars(d, Param(0), time) + SkyStarsFine(d, Param(0) * band * 1.5, time) * 0.7;
    color += stars * smoothstep(-0.02, 0.12, h);

    float3 ground = float3(0.003, 0.003, 0.004);
    return lerp(color, ground, smoothstep(0.0, -0.06, h));
}

float3 EvaluateSky(float3 direction, float time) {
    float3 d = normalize(direction);
    float t = time * Param(2) * 0.01;

    float3 p = d * (1.2 + Param(3) * 1.6) + float3(t, -t * 0.6, t * 0.35);
    float warp = Fbm3(p * 1.4 + 5.0);
    float gas = Fbm3(p + warp * 1.6);
    float hue = Fbm3(p * 2.2 - warp + 11.0);
    float lanes = Fbm3(p * 3.2 + warp + 2.0);

    float body = smoothstep(0.62 - Param(0) * 0.3, 0.95, gas);
    float core = pow(body, 3.0);
    float3 nebula = Palette(hue) * body + lerp(Palette(1.0 - hue), 1.0, 0.35) * core * 0.9;
    nebula *= 1.0 - 0.75 * smoothstep(0.5, 0.75, lanes) * body;

    float3 color = float3(0.004, 0.003, 0.01) + nebula * 0.5 * Param(1);
    color += SkyStars(d, 1.0, time) * (1.0 - body * 0.6) + SkyStarsFine(d, 0.7, time) * 0.8;
    return color;
}

float3 EvaluateSky(float3 direction, float time) {
    float3 d = normalize(direction);
    float h = d.z;

    float elevation = radians(Param(0));
    float azimuth = radians(Param(1));
    float3 sun = float3(cos(elevation) * cos(azimuth), cos(elevation) * sin(azimuth), sin(elevation));
    float mu = dot(d, sun);
    float day = saturate(sun.z * 3.0 + 0.25);

    float3 zenith = lerp(float3(0.04, 0.06, 0.16), float3(0.16, 0.32, 0.72), day);
    float3 horizon = lerp(float3(1.0, 0.36, 0.12), float3(0.9, 0.78, 0.62), saturate(sun.z * 2.5));
    float3 color = lerp(horizon, zenith, pow(saturate(h), 0.4));
    color += float3(1.0, 0.5, 0.2) * pow(saturate(mu * 0.5 + 0.5), 6.0) * (1.0 - saturate(h * 1.5)) * 0.9;
    color += float3(1.0, 0.72, 0.45) * pow(saturate(mu), 48.0) * 1.2;

    color += float3(1.0, 0.85, 0.6) * smoothstep(0.99955, 0.9998, mu) * 40.0;

    [branch]
    if (h > 0.005 && Param(2) > 0.0) {
        float2 p = d.xy / (h + 0.06) * 0.9 + float2(time * Param(3) * 0.01, time * Param(3) * 0.004);
        float shape = Fbm3(float3(p, 0.3));
        float detail = Fbm3(float3(p * 3.5, 1.7));
        float cloud = shape * 0.75 + detail * 0.25;
        float cover = smoothstep(1.02 - Param(2) * 0.55, 1.12 - Param(2) * 0.45, cloud + 0.3);
        float facing = pow(saturate(mu * 0.5 + 0.5), 3.0);
        float3 lit = lerp(float3(0.34, 0.24, 0.3), float3(1.0, 0.62, 0.34), facing) * (0.55 + 0.6 * detail);
        lit += float3(1.0, 0.7, 0.4) * pow(saturate(mu), 12.0) * (1.0 - cover) * 2.0;
        color = lerp(color, lit * (0.4 + day * 0.9), cover * smoothstep(0.005, 0.1, h));
    }

    float3 ground = float3(0.08, 0.06, 0.05) * (0.4 + day);
    return lerp(color, ground, smoothstep(0.0, -0.05, h));
}

float3 EvaluateSky(float3 direction, float time) {
    float3 d = normalize(direction);
    float h = d.z;
    float blend = pow(saturate(h), max(Param(1), 0.05));
    float3 color = lerp(Primary.rgb, Secondary.rgb, blend) * Param(0);
    color += SkyStars(d, Param(2), time) * smoothstep(0.05, 0.3, h);
    float3 ground = Primary.rgb * Param(0) * 0.04;
    return lerp(color, ground, smoothstep(0.0, -0.05, h));
}

float3 EvaluateSky(float3 direction, float time) {
    float3 d = normalize(direction);
    float h = d.z;

    float3 base = lerp(float3(0.22, 0.24, 0.27), float3(0.04, 0.045, 0.055), Param(0));
    float3 color = base;

    float beat = floor(time * 0.7);
    float chance = Hash3(float3(beat, 1.7, 3.1));
    float since = frac(time * 0.7) / 0.7;
    float strike = step(1.0 - Param(2) * 0.35, chance) * exp(-since * 9.0) * (0.6 + 0.4 * sin(since * 90.0));
    float angle = Hash3(float3(beat, 9.2, 4.4)) * 6.2831853;
    float3 where = normalize(float3(cos(angle), sin(angle), 0.3));
    float near = pow(saturate(dot(d, where) * 0.5 + 0.5), 18.0);

    [branch]
    if (h > -0.02) {
        float2 p = d.xy / (h + 0.1) * 1.4 + float2(time * Param(1) * 0.05, time * Param(1) * 0.02);
        float big = Fbm3(float3(p, time * 0.015));
        float small = Fbm3(float3(p * 3.5, time * 0.04));
        float thick = saturate(big * 1.5 - 0.3 + small * 0.35);
        float3 cloud = lerp(base * 1.9, base * 0.45, thick);
        cloud += float3(0.75, 0.8, 1.0) * strike * near * (0.3 + thick) * 2.2;
        color = lerp(color, cloud, smoothstep(-0.02, 0.06, h));
        color = lerp(color, base * 1.4, exp(-h * 9.0) * 0.6);
    }
    color += float3(0.6, 0.65, 0.8) * strike * 0.06;

    float3 ground = base * 0.2;
    return lerp(color, ground, smoothstep(0.0, -0.06, h));
}

cbuffer blur_constants : register(b0) {
    row_major float4x4 current_to_previous;
    row_major float4x4 inverse_projection;
    float4 size;
    float4 params;
};

Texture2D scene_color : register(t0);
#ifdef MULTISAMPLE
Texture2DMS<float> scene_depth : register(t1);
#else
Texture2D<float> scene_depth : register(t1);
#endif
SamplerState linear_clamp : register(s0);

float load_depth(int2 pixel) {
#ifdef MULTISAMPLE
    float depth = params.w > 0.5 ? 0.0 : 1.0;
    uint count = (uint)params.z;
    for (uint i = 0; i < count; i++) {
        float value = scene_depth.Load(pixel, i);
        depth = params.w > 0.5 ? max(depth, value) : min(depth, value);
    }
    return depth;
#else
    return scene_depth.Load(int3(pixel, 0));
#endif
}

bool is_far(float depth) {
    return params.w > 0.5 ? depth <= 0.0 : depth >= 1.0;
}

float4 ndc_of(float2 pixel, float depth) {
    float2 uv = pixel * size.zw;
    return float4(uv * float2(2.0, -2.0) + float2(-1.0, 1.0), depth, 1.0);
}

float view_depth(float4 ndc) {
    return abs(dot(inverse_projection[2], ndc)) / max(abs(dot(inverse_projection[3], ndc)), 1e-8);
}

float4 ps_main(float4 position : SV_Position, float2 unused : TEXCOORD0) : SV_Target {
    float2 pixel = position.xy;
    float4 base = scene_color.SampleLevel(linear_clamp, pixel * size.zw, 0);
    float depth = load_depth(int2(pixel));
    float4 ndc = ndc_of(pixel, depth);
    float4 previous = mul(current_to_previous, ndc);

    [branch]
    if (previous.w <= 1e-6 || any(isnan(previous)) || any(isinf(previous))) return base;

    float2 previous_pixel = (previous.xy / previous.w * float2(0.5, -0.5) + 0.5) * size.xy;
    float2 velocity = (previous_pixel - pixel) * params.x;
    float speed = length(velocity);

    [branch]
    if (isnan(speed) || isinf(speed) || speed < 0.5) return base;

    velocity *= min(params.y / speed, 1.0);
    int samples = clamp((int)ceil(min(speed, params.y)) + 1, 2, 32);
    float last = (float)(samples - 1);
    float center = view_depth(ndc);
    bool sky = is_far(depth);
    float tolerance = max(center * 0.08, 2.0);
    float3 sum = base.rgb;
    float weight = 1.0;

    [loop]
    for (int i = 1; i < samples; i++) {
        float2 p = velocity * ((float)i / last) + pixel;
        if (any(p < 0.5) || any(p > size.xy - 0.5)) continue;
        float d = load_depth(int2(p));
        if (is_far(d) != sky) continue;
        float w = sky ? 1.0 : max(1.0 - abs(view_depth(ndc_of(p, d)) - center) / tolerance, 0.0);
        sum += scene_color.SampleLevel(linear_clamp, p * size.zw, 0).rgb * w;
        weight += w;
    }

    return float4(sum / weight, base.a);
}

cbuffer glow_constants : register(b0) {
    float4 step_sigma;
    float4 tint;
};

Texture2D source : register(t0);
SamplerState linear_sampler : register(s0);

struct vs_output {
    float4 position : SV_Position;
    float2 uv : TEXCOORD0;
};

vs_output vs_main(uint id : SV_VertexID) {
    vs_output output;
    float2 uv = float2((id << 1) & 2, id & 2);
    output.uv = uv;
    output.position = float4(uv * float2(2.0, -2.0) + float2(-1.0, 1.0), 0.0, 1.0);
    return output;
}

float blurred(float2 uv, int channel) {
    float sigma = step_sigma.z;
    float value = 0.0;
    float total = 0.0;
    [unroll] for (int i = -12; i <= 12; i++) {
        float weight = exp(-(i * i) / (2.0 * sigma * sigma));
        float4 texel = source.Sample(linear_sampler, uv + step_sigma.xy * i);
        value += (channel == 3 ? texel.a : texel.r) * weight;
        total += weight;
    }
    return value / total;
}

float4 ps_alpha(vs_output input) : SV_Target {
    float a = blurred(input.uv, 3);
    return float4(a, a, a, a);
}

float4 ps_tint(vs_output input) : SV_Target {
    float a = saturate(blurred(input.uv, 0) * step_sigma.w) * tint.a;
    return float4(tint.rgb, a);
}

panel = $.CreatePanel('MapPlayerPreviewPanel', frame, '$PANEL$', {
    player: true,
    camera: 'cam_char_inspect_wide_intro',
    animgraphcharactermode: 'inventory-inspect',
    playername: 'vanity_character',
    mouse_rotate: false,
    sync_spawn_addons: true,
    hide_while_waiting_for_composite_materials: false,
    'require-composition-layer': true,
    'composition-layer-texture-name': '$LAYER$',
    'transparent-background': true,
    map: 'warehouse_vanity',
    'disable-depth-of-field': false,
    hittest: false,
    style: 'width: 100%; height: 100%;'
});
if (panel) {
    if (panel.SetHideStaticGeometry) panel.SetHideStaticGeometry(true);
    if (panel.SetHideParticles) panel.SetHideParticles(true);
    if (panel.SetTransparentBackground) panel.SetTransparentBackground(true);
}
